import{CARDS,OATHS,VERSES,DEPARTURE,fresh,restore,play,endTurn,incoming,reason,preview,reward,rest,route,damage,effectiveBlock,clanCards,adoptVerse,sever,waterChoice,depart,continueStory,setRetain}from'./engine.mjs?v=3';
import{POEM,SOURCE}from'./poem.mjs';
const $=s=>document.querySelector(s),n=v=>new Intl.NumberFormat('ar-SA').format(v),KEY='shanfara-poem-v2';let s=null,selected=null,selectedTarget=null,sacrificeChoice=null;
try{s=restore(JSON.parse(localStorage.getItem(KEY)))}catch{}
const paths={arrow:'M5 27 27 5M13 5h14v14M5 19v8h8',blade:'m8 26 15-18 5-4-2 8L12 28m-7-7 10 9',shield:'M16 3 28 8v9c0 8-12 13-12 13S4 25 4 17V8Z',trail:'M5 28c22 0-7-13 12-15s5-8 10-10',sun:'M16 9a7 7 0 1 0 0 14 7 7 0 0 0 0-14ZM16 1v4m0 22v4M1 16h4m22 0h4M5 5l3 3m16 16 3 3M27 5l-3 3M8 24l-3 3',wolf:'m4 24 3-15 7 5h5l7-7 3 17-8 6h-8ZM11 20h2m8 0h2m-8 5h5'};
const icon=(type,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[type]||paths.sun}"/></svg>`;
function art(){return`<svg viewBox="0 0 1000 260" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#27363c"/><stop offset="1" stop-color="#9c7961"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h1000v260H0z"/><circle cx="735" cy="62" r="27" fill="#dcd2a9"/><path fill="#344043" d="M0 170 110 55 180 130 285 90 390 179 520 94 630 160 810 120 1000 190v70H0Z"/><path fill="#252e30" d="m0 203 210-80 112 91 208-60 100 65 211-54 159 66v29H0Z"/><path fill="#a17c58" d="M0 245q180-57 380-13t620 2v26H0Z"/><g fill="#121c20" transform="translate(440 137)"><circle cx="0" cy="2" r="8"/><path d="m-7 11-11 44 11 12-5 45h8l9-43 8 43h8L9 56 7 14Zm-8 10-15 27 4 5 20-24 21 22 5-4L8 18Z"/><path d="M22 6q22 30 0 63" fill="none" stroke="#d5bd8c" stroke-width="2"/></g><g fill="#20292a" transform="translate(560 225)"><path d="m-30-8 15-10 30 5 12-12 3 13 12 7-5 5H21l-1 17h-5L9 0h-19l-8 17h-5l4-21-15 5Z"/></g></svg>`}
function save(){try{if(s)localStorage.setItem(KEY,JSON.stringify(s));else localStorage.removeItem(KEY)}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function frame(content){document.body.classList.toggle('playing',s?.phase==='battle');$('#app').innerHTML=`<header><a href="./" class="brand">الشنفرى <span>خارج القبيلة</span></a><nav><button data-action="poem">الديوان</button><button data-action="help" aria-label="طريقة اللعب">؟</button>${s?'<button data-action="deck">مجموعتي</button><button data-action="restart">رحلة جديدة</button>':''}</nav></header>${content}<footer>تجربة إبداعية مستوحاة من الشنفرى ولامية العرب · نموذج رحلة قصيرة</footer>`}
function intro(){let previous=false;try{previous=!!localStorage.getItem('shanfara-exile-v1')}catch{}frame(`<main class="intro"><section class="hero"><div class="landscape">${art()}</div><div class="hero-copy"><span class="eyebrow">لامية العرب • رحلة بطاقات من ثلاثة فصول</span><h1>بين القوم<br><em>والصحراء</em></h1><p>ما زلتَ تحمل زادهم وحمايتهم وطريقهم. تعلّم كيف تستغني، واختر متى تحسم الرحيل.</p></div></section>${previous?'<a class="previous-save" href="previous/">رحلتك في النسخة السابقة محفوظة · تابعها هنا ←</a>':''}<section class="choose"><span class="eyebrow">قبل مفارقة الديار</span><h2>بماذا تستعدّ للرحيل؟</h2><p class="muted">كل بداية تحمل ثلاث بطاقات اعتماد على القوم. ستختار لاحقًا ما تتخلى عنه وما تبنيه بدلًا منه.</p><div class="oaths">${Object.entries(OATHS).map(([id,o])=>`<button class="oath" data-oath="${id}">${icon(CARDS[o.card].icon)}<h3>${o.name}</h3><p>${o.line}</p><div class="gain">+ ${o.gain}</div><div class="cost-text">− ${o.cost}</div><span class="start-label">ابدأ بهذه الاستعدادات ←</span></button>`).join('')}</div><p class="hint">الفصل الأول: الاعتماد · الثاني: الزاد المشترك · الثالث: الفراق. تتبنى معاني أبيات، وتختبر كلفتها في اللعب. لا يوجد عداد «شرف».</p></section></main>`)}
function stats(){return`<section class="stats" aria-label="حال الرحلة"><div><span>الصحة</span><strong class="health"><bdi dir="rtl">${n(s.hp)} من ${n(s.maxHp)}</bdi></strong></div><div><span>الطاقة</span><strong class="gold">${n(s.energy||0)}</strong></div><div><span>الاتقاء</span><strong>${n(s.block||0)}</strong></div><div><span>الزاد</span><strong>${n(s.rations)}</strong></div><div class="companion"><span>الرفقة</span><strong>${s.wolf?'السِّيد معك':'وحيد'}</strong></div></section>`}
function battle(){
 const forecasts=incoming(s),total=forecasts.reduce((a,x)=>a+x.loss,0),id=selected!==null?s.hand[selected]:null,c=CARDS[id],targeted=!!(c&&(c.damage||c.weak)),err=c?reason(s,selected,selectedTarget,sacrificeChoice):'',p=c&&!err?preview(s,selected,selectedTarget,sacrificeChoice):null;
 const alive=s.enemies.filter(e=>e.hp>0),dead=s.enemies.length-alive.length;
 let message=c?(shortText(id)):'اختر بطاقة، ثم هدفها، ثم أكّد التنفيذ.';
 let outcome=c?(err||(p?.phase==='reward'||p?.phase==='victory'?'تحسم هذه الضربة المواجهة':p?.phase==='defeat'?'ستنقطع رحلتك: هذه الحماية لا تكفي':p?.endedTurn?`ينتهي الدور فورًا؛ تتلقى ${n(p.incoming)} ضرر`:`بعدها: ${n(p?.incoming||0)} ضرر يصلك بنهاية الدور${p?.combo?' · إتمام مفعّل':''}`)):s.wolf?`السِّيد: ${s.wolfUsed?'ساعدك هذا الدور':'أول ضربة هذا الدور +٣ ضرر'}`:s.stage===0&&s.turn===1?'طاقتان الآن؛ ٣ طاقة في الأدوار التالية.':s.retain!==null?`أبقيتَ «${CARDS[s.hand[s.retain]].name}»: تنتقل للدور التالي وتسحب ٤ بدل ٥.`:s.lastSetup?`تمهيد ${s.lastSetup} جاهز؛ بطاقة أخرى تقطع التسلسل.`:'يمكنك إبقاء بطاقة واحدة بدل سحب بطاقة جديدة.';
 frame(`<main class="game"><div class="chapter"><div><span class="eyebrow">المواجهة ${n(s.stage+1)} / ٣</span><h1>${['عون القوم','الزاد المشترك',s.departed?'خارج القبيلة':'الفراق المؤجّل'][s.stage]}</h1></div><span class="turn">الدور ${n(s.turn)}</span><button class="log-button" data-action="log" aria-label="سجل المواجهة">أبياتي</button></div>${stats()}<section class="battlefield" aria-label="الخصوم ونياتهم"><div class="scene">${art()}</div><div class="enemies">${alive.map(e=>{
 let f=forecasts.find(x=>x.id===e.id),r=c&&targeted?reason(s,selected,e.id,sacrificeChoice):'لا بطاقة',ep=c&&targeted&&!r?preview(s,selected,e.id,sacrificeChoice):null;
 return `<button class="enemy ${ep?'targetable':''} ${selectedTarget===e.id?'chosen-target':''}" data-target="${e.id}" aria-pressed="${selectedTarget===e.id}" aria-label="${e.name}، ${n(e.hp)} صحة. ${f.call?'يستدعي مطاردًا':enemyIntent(e,f)}"><div class="enemy-top">${icon(e.id==='caller'?'sun':'blade')}<strong>${e.name}</strong></div><div class="enemy-vitals"><bdi dir="ltr">${n(e.hp)} / ${n(e.maxHp)}</bdi><div class="hp-track"><i style="width:${e.hp/e.maxHp*100}%"></i></div></div><p class="intent">${f.call?'⚑ يستدعي مطاردًا':enemyIntent(e,f)}</p>${ep?`<div class="target-preview">${ep.damage?`${n(ep.damage)} ضرر عليه`:`−${n(c.weak||0)} من هجومه`}${ep.damage>=e.hp?' · يسقط':''}<br><b>${selectedTarget===e.id?'✓ هدفك المحدد':'اضغط لتحديده'}</b></div>`:''}</button>`}).join('')}</div>${dead?`<span class="fallen">سقط ${n(dead)} من المطاردين</span>`:''}</section><section class="threat" aria-live="polite"><span>نهاية الدور</span><strong>${n(total)} ضرر يصلك</strong>${forecasts.some(x=>x.call)?'<small>+ مطارد جديد</small>':''}</section><section class="action-preview ${c?'has-selection':''}" aria-live="polite"><div><strong>${c?c.name:'دورك الآن'}</strong><p>${message}</p><small>${outcome}</small></div>${c?`<div class="selection-tools"><button data-action="retain" aria-pressed="${s.retain===selected}">${s.retain===selected?'✓ مُبقاة':'إبقاء ↶'}</button><button class="quiet" data-action="cancel" aria-label="إلغاء اختيار البطاقة">×</button></div>`:''}</section><section class="hand-zone"><div class="hand-heading"><h2>يدك <span>${n(s.hand.length)} · اسحب أفقيًا</span></h2><button data-action="piles">السحب ${n(s.deck.length)} · المطروح ${n(s.discard.length)}</button></div><div class="hand" aria-label="بطاقاتك، اسحب أفقيًا لرؤية البقية">${s.hand.map((id,i)=>card(id,i)).join('')}</div></section><div class="turn-end"><button class="primary play-action" data-action="${c?.sacrifice&&sacrificeChoice===null?'choose-sacrifice':'confirm'}" ${!c||(err&&!(c.sacrifice&&sacrificeChoice===null))?'disabled':''}>${!c?'اختر بطاقة':c.sacrifice&&sacrificeChoice===null?'اختر ما تستنفده':targeted&&!selectedTarget?'حدّد خصمًا':c.end?'احتمِ وأنهِ الدور':`نفّذ · ${n(c.cost)} طاقة`}</button><button class="end" data-action="end">أنهِ الدور ←</button></div></main>`);
}
function card(id,i=null){let c=CARDS[id],unavailable=i!==null&&(s.energy<c.cost||(id==='feed'&&s.rations<1)),d=c.damage&&s?damage(s,id,i):null;return`<button class="card ${c.clan?'clan-card':''} ${s?.retain===i&&i!==null?'retained':''} ${selected===i&&i!==null?'selected':''} ${unavailable?'unavailable':''}" ${i!==null?`data-card="${i}"`:`data-reward="${id}"`}><div class="card-head"><span>${c.kind}${i!==null&&s.retain===i?' ↶':''}</span><b>${n(c.cost)}</b></div>${icon(c.icon,'card-icon')}<h3>${c.name}</h3><p>${i!==null?compact(id,i):c.text}</p>${i!==null?`<small>${unavailable?'لا تكفي مواردك':d?`الضربة الآن ${n(d+(s.wolf&&!s.wolfUsed?3:0))}`:'اضغط للاختيار'}</small>`:''}</button>`}
function compact(id,i){const c=CARDS[id],d=damage(s,id,i)+(s.wolf&&!s.wolfUsed&&c.damage?3:0);return({clanwall:'١٠ اتّقاء · ينهي دورك',clanfood:'+٥ صحة · تُستنفد',clantrail:'اسحب ٢ · اطرح عشوائيًا',endure:`${n(effectiveBlock(s,id,i))} اتّقاء · تمهيد`,steady:`${n(effectiveBlock(s,id,i))} اتّقاء · اسحب ١`,study:'−٥ هجوم · اسحب ١',offering:`${n(effectiveBlock(s,id,i))} اتّقاء · طاقة لاحقًا`,intercept:`${n(effectiveBlock(s,id,i))} اتّقاء · تمهيد`,letgo:'استنفد أخرى · +١ طاقة',riposte:`${n(d)} ضرر · إتمام جَلَد`,opening:`${n(d)} ضرر · إتمام حيلة`,arrow:`${n(d)} ضرر`,blade:`${n(d)} ضرر`,trick:'−٤ هجوم',feed:'رفقة مقابل زاد',hunger:`${n(d)} ضرر`,run:`${n(effectiveBlock(s,id,i))} اتّقاء · اسحب ١`,resolve:'−٢ صحة · اسحب ٢',wolf:`${n(d)} ضرر · ٤ اتّقاء`,ambush:`${n(d)} ضرر`,mend:'+٤ صحة · تُستنفد',salvage:'استعد سهمًا',sand:`${n(d)} ضرر · −٧ هجوم`,double:`${n(d)} ضرر · −٢ صحة`})[id]||c.text}
function enemyIntent(e,f){if(e.id==='watcher'&&s.turn%2===1)return `رصد ${n(f.damage)} · التالي ${n(11+e.attack-7)}`;return `${e.plan.label==='هجوم'?'هجوم':'اندفاع ثقيل'} ${n(f.damage)}`}
function shortText(id){return({clanwall:'١٠ اتّقاء، ثم ينتهي دورك فورًا وتنفّذ الخصوم نياتها.',clanfood:'استعد ٥ صحة. تُستنفد لبقية المواجهة، وتبقى في مجموعتك.',clantrail:'اسحب بطاقتين ثم اطرح واحدة عشوائيًا؛ قد تخسر بطاقة تحتاجها.',feed:'أنفق زادًا واحدًا لتكسب رفقة الذئب وبطاقته طوال الرحلة.',riposte:'١٠ ضرر؛ ١٦ بعد تمهيد جَلَد مباشرة.',opening:'٦ ضرر؛ ١١ بعد تمهيد حيلة مباشرة.',endure:'٧ اتّقاء وتمهيد جَلَد. العب إتمامه بعده مباشرة.',steady:'٥ اتّقاء وسحب بطاقة. تمهيد جَلَد.',trick:'−٤ من هجوم الخصم. تمهيد حيلة؛ لا يمنع الاستدعاء.'})[id]||CARDS[id].text}
function verseBlock(v){return `<blockquote class="verse"><span>${v[0]}</span><span>${v[1]}</span></blockquote>`}
function rewardWhy(id){let c=CARDS[id];if(c.finish){let count=s.master.filter(x=>CARDS[x].setup===c.finish).length;return `عندك ${n(count)} بطاقة تمهيد ${c.finish}. الإتمام ينافس اللعب بترتيب آخر.`}if(id==='letgo')return 'تبادل خيارًا مستقبليًا بطاقة إضافية الآن. الاستنفاد يختلف عن المفارقة الدائمة.';if(c.setup)return 'تمهيد مستقل الفائدة؛ يدعم بطاقة الإتمام المناسبة.';if(id==='offering')return 'تتنازل عن دفاع أقوى الآن لتجهز طاقة للدور التالي.';return 'قارن فائدتها بمساحة السحب التي ستشغلها في مجموعتك.'}
function interlude(){let content='';
 if(s.phase==='reward')content=`<span class="eyebrow">تعلّم أداة لاستقلالك</span><h1>كيف تبني أسلوبك؟</h1><p>اختر بطاقة، أو تجاوز المكافأة لتحافظ على خفة المجموعة.</p><div class="rewards">${s.rewards.map(id=>`<div class="reward-option">${card(id)}<p>${rewardWhy(id)}</p></div>`).join('')}</div><button data-reward="skip" class="quiet">لا أضيف بطاقة</button>`;
 if(s.phase==='verse')content=`<span class="eyebrow">بيتٌ تتبنى معناه · ${n(s.verses.length)} من ٢</span><h1>بأي معنى تتمسّك؟</h1><p>يغيّر البيت قواعد رحلتك، ويضيف بطاقة تساعدك على تطبيقه. هذه معالجة إبداعية للمعنى.</p><div class="verse-options">${Object.entries(VERSES).filter(([id])=>!s.verses.includes(id)).map(([id,v])=>`<button data-verse="${id}"><h2>${v.name}</h2>${verseBlock(v.verse)}<p>${v.meaning}</p><strong>${v.rule}</strong><small>تنضم «${CARDS[v.card].name}»: ${CARDS[v.card].text}</small><span class="start-label">أتبنّى هذا المعنى ←</span></button>`).join('')}</div>`;
 if(s.phase==='sever')content=`<span class="eyebrow">بناء المجموعة هو قصة الفراق</span><h1>ما الذي تستطيع الاستغناء عنه؟</h1><p>المفارقة تزيل البطاقة من الرحلة نهائيًا. الاحتفاظ يمنحك ٤ صحة الآن، ويبقي الاعتماد في سحبك.</p><div class="choices">${[...new Set(clanCards(s))].map(id=>`<button data-sever="${id}"><strong>أفارق: ${CARDS[id].name}</strong><span>${CARDS[id].text}</span><small>تُزال نسخة واحدة من مجموعتك؛ لا تعود في المواجهة التالية.</small></button>`).join('')}<button data-sever="keep"><strong>لستُ مستعدًا للتخلّي</strong><span>أحتفظ بالبطاقات وأستعيد ٤ صحة.</span></button></div>`;
 if(s.phase==='water')content=`<span class="eyebrow">الفصل الثاني · الزاد المشترك</span><h1>قليلٌ من الماء</h1><p>بلغتَ موردًا شحيحًا، ومعك ${s.wolf?'السِّيد المنهك':'عابر عطشان لحق بالطريق'}. الماء لا يكفيكما للتعافي الكامل، والمطاردون يقتربون.</p><div class="choices"><button data-water="self"><strong>أشرب أولًا</strong><span>استعد ٨ صحة. لا مساعدة إضافية في المواجهة التالية.</span></button><button data-water="share"><strong>أقدّم ${s.wolf?'السِّيد':'العابر'} على نفسي</strong><span>تتحمل العطش وتخسر صحتين (تبقى واحدة على الأقل). يساعدك ${s.wolf?'رفيقك':'العابر'} فتبدأ المواجهة التالية بطاقة طاقة إضافية.</span></button><button data-water="search"><strong>أبحث عن ماء يكفينا</strong><span>اكسب زادًا واحدًا، واخسر ٣ صحة (تبقى واحدة على الأقل). يقترب المطارد: هجوم الخصم الأول في المواجهة التالية +٢.</span></button></div>`;
 if(s.phase==='waterverse')content=`<span class="eyebrow">الموقف ثم المعنى</span><h1>${s.waterChoice==='share'?'قدّمتَ غيرك وأنت محتاج':s.waterChoice==='self'?'حفظتَ قوتك أولًا':'اشتريتَ الماء بالوقت والمشقّة'}</h1>${verseBlock(VERSES.generosity.verse)}<p>${s.waterChoice==='share'?'تحملتَ شيئًا من العطش بدل التعافي. بقي ثمن الإيثار في صحتك، وبقيت المساعدة للمواجهة التالية.':s.waterChoice==='self'?'اخترتَ التعافي الأكبر. البيت يضع أمامك سؤال التعفف عن مزاحمة غيرك؛ لا يتغير قرارك بأثر رجعي.':'حاولتَ الجمع بين الحاجتين، لكن الاقتراب من الخطر كان ثمنًا حقيقيًا.'}</p><p class="muted">معنى البيت: ألّا يحملك الحرص على سبق غيرك إلى الزاد. الموقف تطبيق إبداعي، وليس حادثة تاريخية.</p><button class="primary" data-action="continue-story">أتابع بما اخترت</button>`;
 if(s.phase==='departure')content=`<span class="eyebrow">الفصل الثالث · لحظة الفراق</span><h1>هل تقدر أن تمضي دونهم؟</h1><p>فارقتَ ${n(s.removed.length)} من بطاقات الاعتماد. بقي في مجموعتك ${n(clanCards(s).length)}:</p><div class="dependency-list">${clanCards(s).map(id=>`<p><b>${CARDS[id].name}</b> — ${CARDS[id].text}</p>`).join('')||'<p>لم تبق بطاقة اعتماد. بقي أن تحسم الرحيل.</p>'}</div><div class="choices"><button data-depart="yes"><strong>أشدّ رحالي وأمضي</strong><span>أزل كل بطاقات القوم المتبقية نهائيًا. لن تستطيع استخدام المأوى الآمن بعد الرحيل.</span></button><button data-depart="no" ${s.hp<=3?'disabled':''}><strong>أؤجل الرحيل</strong><span>احتفظ بعونهم وبالمأوى. الانتظار تحت المطاردة يكلّف ٣ صحة؛ تحتاج أكثر من ٣.</span></button></div>`;
 if(s.phase==='recital')content=`<span class="eyebrow">البيت الأول صار قرارًا عشته</span><h1>أقيموا بني أُمّي</h1>${verseBlock(DEPARTURE)}<p>تخليتَ عن آخر عون للقوم. المجموعة التي تدخل بها المواجهة القادمة خالية من زادهم وحمايتهم وطريقهم.</p><p class="muted">معنى المطلع: إعلان مفارقة القوم والميل إلى غيرهم. ظهور البيت هنا لا يعني أن هذه الحادثة سبب نظمه.</p><button class="primary" data-action="continue-story">إلى حياة أصنعها بنفسي ←</button>`;
 if(s.phase==='camp')content=`<span class="eyebrow">بين فصلين</span><h1>ليلةٌ على الطريق</h1><p>${s.departed?'أغلقتَ طريق الاعتماد على القوم. يبقى زادك واحتمالك.':s.wolf?'يرقب السِّيد الطريق حين يغلبك النعاس. ما زال المأوى القديم متاحًا.':'لم تحسم كل أوجه الاعتماد بعد. المأوى عند أطراف الديار متاح.'}</p><div class="choices">${!s.departed?'<button data-rest="safe"><strong>أستعين بمأوى الديار</strong><span>استعد ٨ صحة، وأضف نسخة من «نصيب من زاد القوم» إلى مجموعتك. الراحة تعيد بعض الاعتماد.</span></button>':'<div class="locked">المأوى الآمن وراءك؛ حسمتَ الفراق.</div>'}<button data-rest="food" ${!s.rations?'disabled':''}><strong>آكل من زادي</strong><span>أنفق زادًا واحدًا واستعد ١٢ صحة.</span></button><button data-rest="wild"><strong>أبيت في العراء</strong><span>استعد ٣ صحة واحتفظ بزادك.</span></button></div>`;
 if(s.phase==='route')content=`<span class="eyebrow">اختر كلفة الطريق</span><h1>أيّ الطريقين تسلك؟</h1><div class="choices"><button data-route="ridge"><strong>شِعب الصخر</strong><span>${s.stage===0?'راصد يتأنّى: هجومه يتناوب بين ٣ و١١، ومعه قصّاص أثر.':'إلى مخرج الوادي مباشرة؛ لا زاد إضافي.'}</span></button><button data-route="water"><strong>أمرّ بالمورد</strong><span>اكسب زادًا واحدًا. ${s.stage===0?'حارس أقوى: ٣٤ صحة وهجوم ٩، ومعه قصّاص أثر.':'الالتفاف يكلّف ٤ صحة؛ تبقى واحدة على الأقل.'}</span></button></div><p class="muted">${s.waterChoice==='search'&&s.stage===0?'بحثك السابق عن الماء يزيد هجوم الخصم الأول ٢ في الطريقين.':''}</p>`;
 frame(`<main class="interlude"><div class="journey-summary"><span>الصحة ${n(s.hp)} من ${n(s.maxHp)}</span><span>الزاد ${n(s.rations)}</span><span>اعتماد القوم ${n(clanCards(s).length)}</span></div><section class="story">${content}</section></main>`);
}
function ending(){frame(`<main class="ending"><div class="story-art">${art()}</div><span class="eyebrow">${s.phase==='victory'?'انتهت الرحلة القصيرة':'انقطعت الرحلة'}</span><h1>${s.phase==='victory'?(s.departed?'صنعتَ طريقًا خارجهم':'نجوتَ وبقي الفراق مؤجلًا'):'للمضيّ كلفة'}</h1>${s.departed?verseBlock(DEPARTURE):''}<p>${s.phase==='victory'?'ما حدث في الرحلة أهم من عدد من أسقطتهم. هذه هي الآثار التي تركتها قراراتك:':'نفدت صحتك. تبقى الرحلة التالية فرصة لتجربة استعداد مختلف، ومعنى آخر، وتوقيت جديد للفراق.'}</p><div class="recap"><p>صحة ${n(s.hp)} · زاد ${n(s.rations)} · مجموعة ${n(s.master.length)} بطاقات</p><p>فارقتَ ${n(s.removed.length)} من بطاقات القوم؛ بقي ${n(clanCards(s).length)}.</p><p>الأبيات المتبناة: ${s.verses.map(id=>VERSES[id].name).join('، ')||'لم تتبنّ بيتًا بعد'}</p>${s.choices.map(x=>`<p>• ${x}</p>`).join('')}</div><button class="primary" data-action="restart">أبدأ رحلة أخرى</button><button class="quiet" data-action="poem">أقرأ اللامية</button></main>`)}
function render(){let hand=$('.hand'),scroll=hand?.scrollLeft||0;save();if(!s)intro();else if(s.phase==='battle')battle();else if(['victory','defeat'].includes(s.phase))ending();else interlude();if($('.hand'))$('.hand').scrollLeft=scroll;}
function modal(html){$('#dialog').innerHTML=`<button class="close" data-action="close" aria-label="إغلاق">×</button>${html}`;$('#dialog').showModal()}
function execute(target){let r=play(s,selected,target,sacrificeChoice);if(r.error)return toast(r.error);selected=null;selectedTarget=null;sacrificeChoice=null;render();$('.battlefield')?.classList.add('acted')}
function clearSelection(){selected=null;selectedTarget=null;sacrificeChoice=null}
function afterChoice(){clearSelection();render();window.scrollTo(0,0)}
function showPoem(){modal(`<span class="eyebrow">النص كاملًا متاح من البداية</span><h2>لامية العرب</h2><p>القصيدة المنسوبة إلى الشنفرى. قد تختلف بعض ألفاظها وترتيب أبياتها بين الروايات. <a class="source-link" href="${SOURCE}" target="_blank" rel="noopener">مصدر هذا النص: ويكي مصدر ↗</a></p><p class="muted">قواعد اللعبة والمواقف تأويل إبداعي. «إتمام البيت» اسم لتآزر البطاقات، ولا يعلّم الوزن أو تركيب الأبيات.</p>${POEM.map((v,i)=>`<div class="poem-line"><small>${n(i+1)}</small>${verseBlock(v)}</div>`).join('')}`)}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset,a=d.action;
 if(d.oath){s=fresh(d.oath);afterChoice();return}
 if(d.card!==undefined){selected=Number(d.card);selectedTarget=null;sacrificeChoice=null;render();return}
 if(d.target){if(selected!==null&&(CARDS[s.hand[selected]].damage||CARDS[s.hand[selected]].weak)){selectedTarget=d.target;render()}else{let e=s.enemies.find(e=>e.id===d.target);modal(`<h2>${e.name}</h2><p>الصحة: ${n(e.hp)} من ${n(e.maxHp)}.</p><p>${e.plan.label} ${e.plan.type==='attack'?`· ${n(Math.max(0,e.plan.damage-e.weak))} ضرر قبل الاتقاء`:''}</p><p>اختر بطاقة، ثم خصمًا، ثم أكّد التنفيذ.</p>`)}return}
 if(d.reward&&s?.phase==='reward'){reward(s,d.reward);afterChoice();return}
 if(d.verse){adoptVerse(s,d.verse);afterChoice();return}
 if(d.sever){sever(s,d.sever);afterChoice();return}
 if(d.water){waterChoice(s,d.water);afterChoice();return}
 if(d.depart){depart(s,d.depart==='yes');afterChoice();return}
 if(d.rest){rest(s,d.rest);afterChoice();return}
 if(d.route){route(s,d.route);afterChoice();return}
 if(d.sacrifice!==undefined){sacrificeChoice=Number(d.sacrifice);$('#dialog').close();render();return}
 if(a==='continue-story'){continueStory(s);afterChoice();return}
 if(a==='poem'){showPoem();return}
 if(a==='confirm'){if(selected!==null)execute(selectedTarget);return}
 if(a==='choose-sacrifice'){modal('<h2>بأي بطاقة تستغني الآن؟</h2><p>تُستنفد البطاقة المختارة و«أخف مما خرجت» لبقية المواجهة فقط. المفارقة الدائمة قرار آخر بين المواجهات.</p><div class="choices">'+s.hand.map((id,i)=>i===selected?'':`<button data-sacrifice="${i}"><strong>${CARDS[id].name}</strong><span>${CARDS[id].text}</span></button>`).join('')+'</div>');return}
 if(a==='retain'){if(selected!==null){setRetain(s,selected);render()}return}
 if(a==='cancel'){clearSelection();render();return}
 if(a==='end'){if(selected!==null){modal('<h2>إنهاء الدور؟</h2><p>البطاقة المحددة لم تُلعب. تبقى فقط البطاقة التي علّمتها بالإبقاء، وتنفّذ الخصوم نياتها.</p><button class="primary" data-action="end-confirm">أنهِ الدور دون لعبها</button>');return}endTurn(s);clearSelection();render();return}
 if(a==='end-confirm'){$('#dialog').close();clearSelection();endTurn(s);render();return}
 if(a==='log'){modal(`<h2>أبياتي وحال مجموعتي</h2><p>اعتماد القوم: ${n(clanCards(s).length)} بطاقة. ${s.departed?'حسمت الفراق.':'الفراق لم يُحسم.'}</p>${s.verses.map(id=>`<h3>${VERSES[id].name}</h3>${verseBlock(VERSES[id].verse)}<p>${VERSES[id].rule}</p>`).join('')||'<p>بعد المواجهة الأولى ستختار أول بيت تتبنى معناه.</p>'}<h3>سجل المواجهة</h3>${s.log.map(x=>`<p>${x}</p>`).join('')}`);return}
 if(a==='restart'){modal('<h2>رحلة جديدة؟</h2><p>ستفقد تقدم هذه الرحلة. الرحلة المحفوظة في النسخة السابقة تبقى منفصلة.</p><button class="primary" data-action="reset">أبدأ من جديد</button>');return}
 if(a==='reset'){s=null;clearSelection();save();$('#dialog').close();render();return}
 if(a==='close'){$('#dialog').close();return}
 if(a==='help'){modal('<h2>من الاعتماد إلى الفراق</h2><p>تبدأ بثلاث بطاقات للقوم. هي مفيدة، لكنها تقيدك. بعد الفوز تختار مكافأة وبيتًا ثم ما تستطيع مفارقته.</p><p>لعب البطاقة: اخترها، ثم الخصم إن كانت هجومية، ثم نفّذ. «أستظل بحماهم» ينهي الدور فورًا؛ المعاينة تحسب هجمات الخصوم.</p><p>يمكنك إبقاء بطاقة واحدة: اخترها واضغط إبقاء. تنتقل إلى الدور التالي، وتسحب أربعًا بدل خمس. لا تتضاعف مكافأة التحضير بتكرار الاحتفاظ.</p><p>إتمام البيت: تمهيد جَلَد ثم «حد الصبر»، أو تمهيد حيلة ثم «أصيب الغرة». أي بطاقة بينهما تقطع التسلسل. كل بطاقة لها فائدة منفردة.</p><p>الاستنفاد مؤقت للمواجهة. المفارقة تزيل بطاقة الاعتماد من الرحلة. بعد الفصل الثاني تستطيع حسم الفراق كله أو تأجيله.</p><p>موقف الماء يسجل اختيارك ويغير صحتك أو مساعدتك أو ضغط المطاردة؛ لا يوجد عداد شرف. افتح «أبياتي» لمعرفة قواعدك الحالية، و«الديوان» لقراءة النص كاملًا.</p>');return}
 if(a==='deck'||a==='piles'){let ids=a==='deck'?s.master:[...s.deck,...s.discard,...s.exhaust];modal(`<h2>${a==='deck'?'مجموعة رحلتك':'خارج يدك'}</h2><p>${a==='deck'?`بطاقات القوم: ${n(clanCards(s).length)}. ما تفارقه لن يعود في الرحلة.`:'السحب ثم المطروح ثم المستنفد. المستنفد يعود في المواجهة التالية.'}</p><div class="deck-list">${ids.map(id=>`<div class="${CARDS[id].clan?'clan-entry':''}">${icon(CARDS[id].icon)}<strong>${CARDS[id].name}${CARDS[id].clan?' · اعتماد':''}</strong><span>${CARDS[id].text}</span></div>`).join('')}</div>`)}
});
render();
